package com.railway.servlet;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import com.railway.dao.UserDao;import com.railway.model.User;
public class LoginServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if("1".equals(r.getParameter("registered")))r.setAttribute("notice","Registration successful. Please sign in.");r.getRequestDispatcher("/login.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=new UserDao().authenticate(r.getParameter("email"),r.getParameter("password"));if(u==null){r.setAttribute("error","Invalid email or password.");doGet(r,s);return;}HttpSession old=r.getSession(false);if(old!=null)old.invalidate();HttpSession session=r.getSession(true);session.setAttribute("user",u);session.setMaxInactiveInterval(20*60);s.sendRedirect(r.getContextPath()+("ADMIN".equals(u.getRole())?"/admin":"/"));}catch(Exception e){getServletContext().log("Login failed",e);r.setAttribute("error","Sign in is temporarily unavailable.");doGet(r,s);}}}
